export const LingoDexData_lastUpdated:string = "2026-07-22"
export const LingoDexData_ownerSbId:string = "87a351b1-2321-4ff3-acd1-debe08e2d093";

export const LingoDexImgFolderURL:string = "https://designjams.s3.amazonaws.com/lingoframe-20240718/lingoframe-compressed-jpgs-v3/";

const LINGODEX_VARIANT_NUMBERS = [1, 2, 3, 4, 5] as const;

export function numLingoDexEntryVariants(lingoDexEntry:LingoDexEntry):number {
	const qs:string[] = LINGODEX_VARIANT_NUMBERS.map(n => lingoDexEntry[`q${n}`]).filter(Boolean);
	const is:string[] = LINGODEX_VARIANT_NUMBERS.map(n => lingoDexEntry[`i${n}`]).filter(Boolean);
	let numVariants = Math.max(qs.length,is.length);
	return numVariants;
}

export type LingoDexEntryVariant = {
	devref: string;
	variant_index: number;
};

export function getOriginalENWORDSForLingoDexVariant(v:LingoDexEntryVariant):string[] {
   const entry:LingoDexEntry|undefined = LingoDexData.find(e=>e.devref == v.devref);
   if (!entry) throw new Error(`LingoDex entry not found for devref: ${v.devref}`);
   const qs = LINGODEX_VARIANT_NUMBERS.map(n => entry[`q${n}`]).filter(Boolean);
   const q = qs.length <= 1 ? qs[0] : qs[v.variant_index];
   const answerNumber = LINGODEX_VARIANT_NUMBERS[v.variant_index];
   const a = answerNumber === undefined ? undefined : entry[`a${answerNumber}`];
   const lines:string[] = [q, a].filter(Boolean) as string[];
   const WORDS:string[] = [...new Set(
      lines.flatMap(line => line.split(/[\s\p{P}]+/u).filter(Boolean).map(w => w.toUpperCase()))
   )];
   return WORDS;
}

