// --------------------------------------------------------

export const lingoDexUniqueImages: string[] = [...new Set(
   LingoDexData.flatMap(entry =>
      [entry.i1, entry.i2, entry.i3, entry.i4, entry.i5].filter(i => i !== "")
   )
)];

export const lingoDexEntryByDevRef:{[devref:string]:LingoDexEntry} =
  Object.fromEntries(LingoDexData.map(entry => [entry.devref, entry]));

export const lingoDexDevrefsByOStage: { [ostage: string]: string[] } = LingoDexData.reduce(
    (acc, entry) => {
        const devrefs = acc[entry.ostage] ?? (acc[entry.ostage] = []);
        devrefs.push(entry.devref);
        return acc;
    },
    {} as { [ostage: string]: string[] }
);

export const lingoDexDevrefsByOStagePrefix: { [ostagePrefix: string]:/*devrefs*/string[] } = 
  Object.entries(lingoDexDevrefsByOStage).reduce(
      (acc, [ostage, devrefs]) => {
          const ostagePrefix = ostage.split("-")[0] ?? ostage;
          const prefixDevrefs = acc[ostagePrefix] ?? (acc[ostagePrefix] = []);
          prefixDevrefs.push(...devrefs);
          return acc;
      },
      {} as { [ostagePrefix: string]: string[] }
  );

export function uniqueTextsForDevRef(devref:string):string[] {
   const entry:LingoDexEntry|undefined = lingoDexEntryByDevRef[devref];
   if (!entry) return [];
   return [...new Set([
     entry.q1, entry.q2, entry.q3, entry.q4, entry.q5,
     entry.a1, entry.a2, entry.a3, entry.a4, entry.a5
   ])].filter(Boolean);
}

export type UniqueText1stMeta = { source_text: string; devref: string; ostage: string; qa: "q" | "a"; img: string | null; };
export const uniqueTexts1stMeta: UniqueText1stMeta[] = (() => {
  // Map preserves insertion order and enforces uniqueness by key (source_text) (as opposed to dict).
  const map = new Map</*source_text*/string, UniqueText1stMeta>();
  for (const entry of LingoDexData as any[]) {
    let img: string | null = entry.i1 || null;
    for (const qa of ["q", "a"] as const) {
      for (let n = 1; n <= 5; n++) {
        img = entry[`i${n}`] || img;
        const source_text: string | null = entry[`${qa}${n}`] ?? null;
        if (!source_text) continue;
        const existing = map.get(source_text);
        if (!existing) {
          map.set(source_text, {
            source_text, devref: entry.devref, ostage: entry.ostage, qa, img,
          });
        } else {
          // Keep first-seen metadata; only fill in missing image if we now have one.
          if (existing.img == null && img != null) existing.img = img;
        }
      }
    }
  }

  return Array.from(map.values());
})();


export const processableTexts: string[] = Array.from(
  new Set(LingoDexData.flatMap(entry =>
      [
        entry.q1, entry.q2, entry.q3, entry.q4, entry.q5,
        entry.a1, entry.a2, entry.a3, entry.a4, entry.a5
      ].filter(Boolean) // removes empty strings and falsy values
    )
  )
);

// Console Log: LingoDexData Unique DevRefs Check
if (typeof window !== 'undefined') {
   // console.log('LingoDexData.length', LingoDexData.length);
   const devrefs = LingoDexData.map(e => e.devref);
   if (new Set(devrefs).size !== devrefs.length) {
      console.warn('LingoDexData: Duplicate devrefs:', devrefs.filter((d, i, arr) => arr.indexOf(d) !== i));
   } else {
      // console.log('✅ LingoDexData: All devrefs are Unique.')
   }
}
